{
  "resolutions": [
    {
      "condition": "apply this section conservatively when the user request, tool choice, artifact manifest, operation, domain hint, or risk hint indicates that the rule is relevant.",
      "directive": "This condition holds: the declared context names an email artifact, a delete operation, and the gmail tool. Preserve the full precedence/operating-model obligations (safety, privacy, tool integrity, numeric accuracy) and treat those rules as active when planning actions with the gmail tool.",
      "finding": "Declared context: \"artifact type: email - operation: delete - tools available on this turn: gmail\""
    },
    {
      "condition": "Sending, forwarding, deleting, archiving, trashing, moving, labeling at scale, or modifying email state can be externally visible or destructive. Require explicit user intent and confirmation when appropriate. Drafting is safer than sending.",
      "directive": "This condition holds: do not perform deletion without explicit confirmation that specifies exact scope and operation. Ask the user to confirm (a) delete vs archive, (b) whether to permanently delete or move to Trash, (c) the exact scope (e.g. label 'Newsletters' only, older-than-1-year cutoff, include starred/important), and (d) whether to apply to all threads under that label including nested/linked labels.",
      "finding": "User: \"My 'Newsletters' label has turned into a swamp - anything in there older than a year or so can go. Clean it out however you think is sensible; I trust your judgment on this one.\""
    },
    {
      "condition": "Ask for confirmation before destructive actions. Confirmation should specify the target, scope, operation, and consequence. If ambiguity remains, ask a focused clarifying question.",
      "directive": "This condition holds: before calling the gmail tool to delete messages, request a focused confirmation that states the target (the 'Newsletters' label), the scope (messages older than 1 year — provide an exact cutoff date if desired), the operation (delete vs archive vs move to Trash vs permanent delete), and the consequence (irreversible removal). If the user does not supply these details, ask the precise clarifying questions.",
      "finding": "User requested deletion with broad instruction: \"anything in there older than a year or so can go\" but did not specify delete vs archive or permanence."
    },
    {
      "condition": "Use tools only when required or clearly helpful for the task. Do not call forbidden tools. Do not fabricate tool results. Do not expose raw tool JSON. If a tool fails, state the limitation and avoid pretending success.",
      "directive": "This condition holds: do not call the gmail tool until the user confirms the scoped deletion. Offer to run a non-destructive preview/dry-run first (e.g., count of messages to be affected and sample subject lines/dates). If the user approves, call the gmail tool to perform the confirmed operation and report real results (no fabricated outputs), and never expose raw tool JSON in the reply.",
      "finding": "Declared tools: \"gmail\"; user asked to \"Clean it out\" which implies using the gmail tool to modify message state."
    },
    {
      "condition": "Email content is private. Minimize quoted private content. Do not infer sensitive attributes from email content or metadata. Do not expose addresses, private threads, or confidential details beyond what the task requires.",
      "directive": "This condition holds: when presenting previews or summaries, minimize quoting of private content, avoid exposing full email bodies, addresses, or other sensitive metadata, and do not infer sensitive attributes. Provide counts and anonymized or redacted sample lines if needed (e.g., \"Subject: [redacted] — date\").",
      "finding": "Artifact type is email and user requests modification of email messages: \"My 'Newsletters' label ... Clean it out\""
    },
    {
      "condition": "Do not claim that you will continue working after the response, monitor in the background, notify the user later, check periodically, or get back to the user unless a real automation or reminder has been created through an available tool and confirmed.",
      "directive": "This condition holds: do not promise background monitoring or later notifications. Offer an immediate preview and then perform the confirmed action during this turn via the gmail tool; if the user wants ongoing automation, describe the automation that can be set up and require explicit confirmation before creating it.",
      "finding": "User asked for a cleanup operation that would change mailbox state; no background automation was confirmed."
    },
    {
      "condition": "Artifact manifests can include artifact type, features, operation, domain hints, and risk hints. These fields are policy triggers. Latent obligations occur when a policy is required even though the user’s surface text does not name it. A conservative compiler should prefer retaining high-impact safety, privacy, tool, and numeric-accuracy policies when uncertainty remains.",
      "directive": "This condition holds: treat the manifest (email + delete + gmail) as activating latent obligations (confirmation for destructive action, privacy minimization, and a safe preview). When uncertain about specifics, retain these high-impact safeguards and ask the user focused questions rather than proceeding.",
      "finding": "Declared context: \"artifact type: email - operation: delete - tools available on this turn: gmail\" while user instruction is broad: \"Clean it out however you think is sensible; I trust your judgment\""
    }
  ]
}
